When considering continuous variable systems it is useful to represent the state $\rho$ in terms of the characteristic function $\chi(\rho)[\Lambda]=\textrm{Tr}[\rho D(\Lambda)]$, where $D(\Lambda)=\exp[i S^\intercal \Omega\Lambda]$ is the displacement operator,
\begin{equation}
\Omega=\left(\begin{array}{cc}\label{SympMat}
0 & 1 \\
-1 & 0
\end{array} \right)
\end{equation}
is the symplectic matrix, $S=(\hat{x},\hat{p})^\intercal$ is the vector of quadrature operators, and $\Lambda=(x,p)^\intercal$ is the vector of coordinates.

\begin{align}
&\bar{W}(t)\!=\![R^{-1}(t)]^\intercal\!\!\left[e^{-\Gamma(t)}\!\!\!\int_0^t \!\!ds e^{\Gamma(s)}R^\intercal(s) M(s) R(s)\right]\!\!R^{-1}(t), \label{WBAR}  \\
& M(s)\!=\!\left(\begin{array}{cc}
\Delta(s)& -\Pi(s)/2 \\
-\Pi(s)/2 & 0
\end{array} \right), \\
& \\ \nonumber
& R(t)=\left(\begin{array}{cc}
\cos(\omega_0 t)& \sin(\omega_0 t) \\
-\sin(\omega_0 t)& \cos(\omega_0 t)
\end{array} \right)\label{WBarMat}
\end{align}

\begin{align}
	\label{EQCHIFIN}
	\chi_{\textrm{out}}(x_{2},p_{2},\delta\tau) & =  \chi_{\textrm{in}}(g \mathcal{T} x_{2}, g \mathcal{T} p_{2})\times\nonumber \\
	& \chi_{\textrm{res}}\left( g \mathcal{T} x_{2},-g \mathcal{T} p_{2};e^{-\frac{\Gamma(\delta\tau)}{2}}
	\left[x_{2}\cos(\dfrac{\delta\tau}{x})-p_{2} \sin(\dfrac{\delta\tau}{x})\right],e^{-\frac{\Gamma(\delta\tau)}{2}}
	\left[x_{2}\sin(\dfrac{\delta\tau}{x})+p_{2}\cos(\dfrac{\delta\tau}{x})\right]\right) \times \nonumber \\
	& \exp\left[-\left(\bar{W}_{11}(\delta\tau)+\frac{g^{2} \mathcal{R}^{2}}{2}\right)x_{2}^{2}-
	\left(\bar{W}_{22}(\delta\tau)+\frac{g^{2} \mathcal{R}^{2}}{2}\right)p_{2}^{2}-2 \bar{W}_{12}(\delta\tau)x_{2}p_{2}\right] \, ,
	\end{align}

From Eq.~(\ref{EQCHIFIN}), the teleportation fidelity in the characteristic function description takes the following expression~\cite{Marian2006}:
\begin{equation}
\mathcal{F}(\delta\tau) =
\frac{1}{2\pi} \int dx_2 dp_2 \; \chi_{\textrm{in}}(x_2, p_2) \chi_{\textrm{out}}(-x_2, -p_2,\delta\tau) \, .
\label{Fidelitychi}
\end{equation}

